    pub(super) async fn delete_collection(
        &self,
        collection_name: &str,
    ) -> Result<bool, StorageError> {
        let _collection_create_guard = self.collection_create_lock.lock().await;

        self.alias_persistence.write().await.remove_collection(collection_name)?;

        let to_delete;
        let result;
        let collection_path = self.get_collection_path(collection_name);
        let safe_delete_path = self.storage_config.storage_path.join(".deleted");

        let removed_opt = self.collections.write().await.remove(collection_name);
        if let Some(removed) = removed_opt {
            // ... stop/abort resharding, stop_gracefully, try_unwrap_with_timeout, safe_delete_in_tmp ...
            result = true;
        } else {
            // we hold the collection_create lock to make sure no one is creating this collection
            // otherwise we would delete its content now
            if collection_path.exists() {
                log::warn!("Collection {collection_name} is not loaded, but its directory still exists. Deleting it.");
                to_delete = Some(safe_delete_in_tmp(&collection_path, &safe_delete_path)?);
            } else {
                to_delete = None;
            }

            result = false;          // <-- collection 不存在: 显式 Ok(false)，非 Err(NotFound)
        }

        if let Some(to_delete) = to_delete {
            tokio::task::spawn_blocking(move || { if let Err(error) = to_delete.close() { log::error!("Can't delete collection from disk: {error}"); } });
        }

        Ok(result)
    }

